#!/usr/bin/env python3
"""Add a 'Recommendations' section to quarterly_report.docx (unpacked dir)."""
from pathlib import Path

from defusedxml import minidom

UNPACKED = Path("quarterly_report_unpacked")
DOC_XML = UNPACKED / "word" / "document.xml"
STYLES_XML = UNPACKED / "word" / "styles.xml"


def collect_namespace_decls(dom):
    root = dom.documentElement
    decls = []
    if root is not None and root.attributes:
        for i in range(root.attributes.length):
            attr = root.attributes.item(i)
            if attr.name.startswith("xmlns"):
                decls.append('{}="{}"'.format(attr.name, attr.value))
    return " ".join(decls)


def pick_heading_style(styles_path):
    """Return an existing paragraph heading style id, preferring Heading1."""
    try:
        sdom = minidom.parse(str(styles_path))
    except Exception:
        return "Heading1"
    candidates = []
    for style in sdom.getElementsByTagName("w:style"):
        if style.getAttribute("w:type") not in ("paragraph", ""):
            continue
        sid = style.getAttribute("w:styleId")
        name = ""
        for nm in style.getElementsByTagName("w:name"):
            name = nm.getAttribute("w:val")
            break
        key = (sid + " " + name).lower()
        if key.startswith("heading1") or sid.lower() == "heading1":
            return sid
        if "heading" in key:
            candidates.append(sid)
    if candidates:
        return candidates[0]
    return "Heading1"


def build_section_xml(style_id):
    heading = (
        '<w:p><w:pPr><w:pStyle w:val="{}"/></w:pPr>'
        "<w:r><w:t>Recommendations</w:t></w:r></w:p>"
    ).format(style_id)

    intro = (
        "<w:p><w:r><w:t>Based on this quarter&#8217;s performance and outlook, "
        "management recommends the following actions to build on progress and "
        "address key risks:</w:t></w:r></w:p>"
    )

    items = [
        "1. Sustain the positive momentum by continuing to invest in the areas "
        "that delivered the strongest results this quarter.",
        "2. Maintain disciplined cost management to protect margins while "
        "scaling successful initiatives.",
        "3. Monitor emerging risks closely and update the quarterly forecast "
        "as new information becomes available.",
        "4. Strengthen engagement with key stakeholders by sharing performance "
        "updates and next steps promptly.",
    ]
    body = "".join(
        "<w:p><w:r><w:t>{}</w:t></w:r></w:p>".format(text) for text in items
    )
    return heading + intro + body


def main():
    dom = minidom.parse(str(DOC_XML))
    ns_decls = collect_namespace_decls(dom)

    style_id = pick_heading_style(STYLES_XML)
    section_xml = build_section_xml(style_id)

    wrapper = "<root {}>{}</root>".format(ns_decls, section_xml)
    frag = minidom.parseString(wrapper)
    new_nodes = [
        dom.importNode(child, deep=True)
        for child in frag.documentElement.childNodes
        if child.nodeType == child.ELEMENT_NODE
    ]

    body = dom.getElementsByTagName("w:body")[0]

    # Insert before the body-level final sectPr if present, else append at end.
    anchor = None
    for child in body.childNodes:
        if (
            child.nodeType == child.ELEMENT_NODE
            and child.tagName == "w:sectPr"
        ):
            anchor = child
    for node in new_nodes:
        if anchor is not None:
            body.insertBefore(node, anchor)
        else:
            body.appendChild(node)

    with open(DOC_XML, "wb") as fh:
        fh.write(dom.toxml(encoding="UTF-8"))

    print("Recommendations section added with heading style: " + style_id)
    print("Inserted paragraphs: " + str(len(new_nodes)))


if __name__ == "__main__":
    main()

